#!/usr/bin/env bash
set -euo pipefail
printf '\n=== PLAYSPOTSTORE / NEON V2 ===\n'
if ! command -v git >/dev/null 2>&1 || ! command -v python3 >/dev/null 2>&1; then
  echo 'This updater needs git and Python 3 (both are available in GitHub Codespaces).'; exit 1
fi
ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || { echo 'Open the PlaySpotStore repository in Codespaces first.'; exit 1; }
cd "$ROOT"
case "$(git remote get-url origin 2>/dev/null || true)" in
  *dragoshelemenet/playspotstore*) ;;
  *) echo 'Wrong repository; refusing to modify files.'; exit 1;;
esac
if [ -n "$(git status --porcelain --untracked-files=no)" ]; then
  echo 'You have uncommitted tracked changes. Commit or stash them before running this updater.'
  git status --short
  exit 1
fi
if [ "$(git branch --show-current)" != 'main' ]; then
  echo 'Please switch to main (git switch main) before running the updater.'; exit 1
fi
echo 'Pulling the latest main (fast-forward only)...'
git pull --ff-only origin main
for f in index.html ru.html neon-redesign.css; do
  [ -f "$f" ] || { echo "Missing $f; this does not look like the updated PlaySpotStore repository."; exit 1; }
done
# The updater is additive: it keeps product data and existing functionality untouched.
mkdir -p neon-assets
python3 - <<'PYASSET'
from pathlib import Path
import base64
Path('neon-assets/neon-hero-v2.webp').write_bytes(base64.b64decode(''))
print('  ✓ Sharper gaming hero: neon-assets/neon-hero-v2.webp')
PYASSET
