python3 - <<'PYPATCH'
from pathlib import Path
import re

required = ('index.html', 'ru.html', 'neon-redesign.css')
for p in required:
    if not Path(p).is_file():
        raise SystemExit(f'Missing {p}. Run inside the PlaySpotStore repository after pulling the latest main.')

links = ('  <link rel="stylesheet" href="neon-redesign.css?v=20261104">\n'
         '  <link rel="stylesheet" href="neon-v2.css?v=20261104b">\n'
         '  <link rel="preload" as="image" type="image/webp" href="neon-assets/neon-hero-v2.webp">\n')
ambient = '<div class="hero-ambient" aria-hidden="true"><span class="amb-green"></span><span class="amb-purple"></span></div>'

for filename in ('index.html', 'ru.html'):
    path = Path(filename)
    html = path.read_text(encoding='utf-8')
    # The original installer accidentally placed its stylesheet after </head>.
    # Move that stylesheet into the head and add the V2 stylesheet after it.
    html = re.sub(r'\s*<link\s+rel="stylesheet"\s+href="neon-redesign\.css\?v=[^"]+"\s*/?>', '', html)
    html = re.sub(r'\s*<link\s+rel="stylesheet"\s+href="neon-v2\.css\?v=[^"]+"\s*/?>', '', html)
    html = re.sub(r'\s*<link\s+rel="preload"\s+as="image"\s+type="image/webp"\s+href="neon-assets/neon-hero-v2\.webp"\s*/?>', '', html)
    if html.count('</head>') > 1:
        html = html.replace('</head>', '', html.count('</head>') - 1)
    if html.count('</head>') != 1:
        raise SystemExit(f'Unexpected HTML head in {filename}; no files changed.')
    html = html.replace('</head>', links+'</head>', 1)
    # Replace art but don't disturb the other elements or the built-in catalog JS.
    if 'neon-assets/neon-hero.webp' not in html and 'neon-assets/neon-hero-v2.webp' not in html:
        raise SystemExit(f'No existing neon hero found in {filename}; no files changed.')
    html = html.replace('src="neon-assets/neon-hero.webp" width="890" height="365"',
                        'src="neon-assets/neon-hero-v2.webp" width="1413" height="530"', 1)
    html = html.replace('src="neon-assets/neon-hero.webp"', 'src="neon-assets/neon-hero-v2.webp"', 1)
    if 'hero-ambient' not in html:
        target = '<section class="hero" id="acasa">'
        if target not in html:
            raise SystemExit(f'Expected hero opening tag not found in {filename}; no files changed.')
        html = html.replace(target, target+ambient, 1)
    # Improve accessibility without changing category IDs or adding duplicate listeners.
    html = html.replace('aria-label="Toggle menu"',
                        'aria-label="Open navigation menu"', 1)
    path.write_text(html, encoding='utf-8')
    print('  ✓', filename)
print('  ✓ Existing games, JSON data, product modals, language switch and search preserved.')

